from taf.rfrl.l3_call.enviornment.env import Env
from taf.rfrl.l3_call.connection.api_connection.api_connection_factory import ApiConnectionFactory
from taf.rfrl.l3_call.logger.l3_call_logger import log_to_console, log_result


class CloudEnv(Env):
    def __init__(self):
        super(CloudEnv, self).__init__()
        self._ran = "cloud"
        self._mode = "SA"
        self._node = "gnb"
        self._api_connection = None
        self._cu_connection_alias = ""
        self._du_connection_aliases = []

    def __str__(self):
        return "CloudEnv instance for ran={}, mode={}, node={}".format(self._ran, self._node, self._mode)

    def _is_callable(self, cell_distname):
        cell = self._create_cell(cell_distname=cell_distname, bts_connection_alias=self._du_connection_aliases)
        if not cell.is_iot_cell():
            return True
        log_to_console("IoT cells are not yet callable for Cloud configs!")
        return False

    def _get_cell_id(self, called_cell_distname):
        cell = self._create_cell(cell_distname=called_cell_distname, bts_connection_alias=self._du_connection_aliases)
        return {"gnb_cell": cell.get_cell_id()}

    def _prepare_setup_to_call(self):
        for called_cell in self.called_cells_distnames:
            self._cell = self._create_cell(cell_distname=called_cell, bts_connection_alias=self._du_connection_aliases)
            self._handle_dss()
            self._prepare_called_cell()

        self._prepare_not_called_cells()

    def _prepare_called_cell(self):
        self._called_cell_spectrum = self._cell.get_spectrum()
        self._cell.make_callable()
        log_result("Cell {} is ready to be called!".format(self._cell.distname))

    def _prepare_not_called_cells(self):
        self._get_not_called_cells_distnames()
        if self._not_called_cells_distnames:
            self._delta = self._create_delta(connection_alias=self._cell.vdu_alias, id="not_called_cells")
            for not_called_cell_distname in self._not_called_cells_distnames:
                self._prepare_not_called_cell(not_called_cell_distname=not_called_cell_distname)
            self._delta.perform_delta_recommissioning()
            self._delta.remove_delta()

    def _get_not_called_cells_distnames(self):
        not_called_cells_distnames = []
        cells_status = self._api_connection.admin_du.get_vdu_cells_status(vdu_connection=self._cell.vdu_alias)
        for cell in cells_status:
            distname = cell["dist_names"]["config"]
            if distname != self._cell.distname and distname != self._cell.dss_pair:
                not_called_cells_distnames.append(cell["dist_names"]["config"])
        self._not_called_cells_distnames = not_called_cells_distnames
        log_result("Not called cells: {}".format(self._not_called_cells_distnames))

    def _prepare_not_called_cell(self, not_called_cell_distname):
        cell = self._create_cell(cell_distname=not_called_cell_distname,
                                 bts_connection_alias=self._du_connection_aliases)
        cell_spectrum = cell.get_spectrum()
        shared_spectrum = self._is_spectrum_shared(cell_spectrum_1=self._called_cell_spectrum,
                                                   cell_spectrum_2=cell_spectrum)

        if shared_spectrum:
            cell = self._create_cell(cell_distname=not_called_cell_distname, shared_spectrum=False,
                                     bts_connection_alias=self._du_connection_aliases)
        cell.make_uncallable(delta=self._delta)

    def _open_api_connection(self):
        self._api_connection = ApiConnectionFactory.create_connection(ran=self._ran, node=self._node)
        self._api_connection.connect_to(name="cloud_api")
        self._cu_connection_alias = self._api_connection.admin_cu_alias
        self._du_connection_aliases = self._api_connection.admin_du_aliases

    def _clean_up_after_call(self, close_connection_to_bts):
        self._make_cells_callable()
        self._cell_ids = None
        if close_connection_to_bts:
            self._api_connection.disconnect()

    def _make_cells_callable(self):
        if self._not_called_cells_distnames:
            self._delta = self._create_delta(connection_alias=self._cell.vdu_alias, id="clean_up_delta")
            for not_called_cell_distname in self._not_called_cells_distnames:
                cell = self._create_cell(cell_distname=not_called_cell_distname,
                                         bts_connection_alias=self._du_connection_aliases)
                cell.make_callable(delta=self._delta)
            self._delta.perform_delta_recommissioning()
            self._delta.remove_delta()

    def _verify_pcap(self, cell_distname, pcap_path, attach_should_be_possible=True):
        log_to_console("PCAP verification not yet available for Cloud configs, skipping this step!")

    def _verify_pcap_after_parallel_call(self, cell_distname, pcap_path, number_of_expected_attach_msgs):
        log_to_console("PCAP verification not yet available for Cloud configs, skipping this step!")
